-- Seed 8 real figures into pokemon_models
INSERT INTO pokemon_models (id, pokedex_number, name, category, generation, primary_type, secondary_type, scale, base_print_time_minutes, default_filament_grams, image_url, base_price, is_active)
SELECT 2, 0, 'Zorua', 'FIGURE_POKEMON', 1, 'Escuridão', NULL, 'Padrão (10 cm)', 840, 320, 'data:image/jpeg;base64,', 60, 1
WHERE NOT EXISTS (SELECT 1 FROM pokemon_models WHERE id = 2 OR name = 'Zorua');

